    filters=[]
    for ifi in act.findall('intent-filter'):
        actions=[a.attrib.get(ANDROID+'name') for a in ifi.findall('action')]
        cats=[c.attrib.get(ANDROID+'name') for c in ifi.findall('category')]
        datas=[]
        for d in ifi.findall('data'):
            datas.append({k.split('}',1)[1]:v for k,v in d.attrib.items()})
        filters.append((actions,cats,datas))
    if filters:
        print('##',name)
        for actions,cats,datas in filters:
            print(' actions=',actions)
            if cats: print(' cats=',cats)
            if datas: print(' data=',datas)
